<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {onMount,untrack} from 'svelte';
 import {beforeNavigate} from '$app/navigation';
 import {Save,Upload,Download,Play,ArrowUp,ArrowDown,Plus,Trash2} from 'lucide-svelte';
 import ModuleEditorHeader from '../components/ModuleEditorHeader.svelte';
 import RichTextEditor from './routingtales/shared/RichTextEditor.svelte';
 import RoutingModulePlayer from './RoutingModulePlayer.svelte';
 import MediaField from './MediaField.svelte';
 import {localized,answerModes,imageModes,validateRoutingModule,routingModuleReady,type RoutingContentModule,type LocalizedText,type InfoBlock} from './routing';
 import {importRoutingModule,exportRoutingModule} from './routing-import';
 import {downloadBlob} from '../storage/adventure-package';
 let {module,baseLocale='es',title,onapply,onclose,ondirty}:{module:RoutingContentModule;baseLocale?:string;title:string;onapply:(module:RoutingContentModule)=>void;onclose:()=>void;ondirty:(dirty:boolean)=>void}=$props();
 let draft=$state<RoutingContentModule>(untrack(()=>JSON.parse(JSON.stringify(module)))),initial=$state(''),ready=$state(false),lang=$state(untrack(()=>baseLocale)),customLang=$state(''),tab=$state<'edit'|'json'|'preview'>('edit'),json=$state(''),error=$state(''),discarding=$state(false),previewRevision=$state(0);
 let fileInput:HTMLInputElement;
 const labels={info:'Información',video:'Vídeo',question:'Pregunta'};
 const dirty=$derived(ready&&(JSON.stringify(draft)!==initial||tab==='json'&&json!==JSON.stringify(exportRoutingModule(draft),null,2)));
 const languages=$derived([...new Set([baseLocale,...Object.keys(typeof draft.content.body==='object'?draft.content.body:{}),lang])]);
 const previewStorage={getItem:()=>null,setItem:()=>{}};
 onMount(()=>{initial=JSON.stringify(draft);ready=true;});$effect(()=>ondirty(dirty));
 beforeNavigate(e=>{if(dirty&&!confirm(ui.text("¿Descartar los cambios de este módulo?")))e.cancel();});
 function leave(){if(dirty)discarding=true;else onclose();}
 function keys(e:KeyboardEvent){if(e.key==='Escape'&&!e.defaultPrevented){e.preventDefault();leave();}}
 function unload(e:BeforeUnloadEvent){if(dirty){e.preventDefault();e.returnValue='';}}
 function localizedField(key:string){const value=draft.content[key] as LocalizedText|undefined;return typeof value==='string'?(lang===baseLocale?value:''):value?.[lang]??'';}
 function writeField(key:string,value:string){const before=draft.content[key];draft={...draft,content:{...draft.content,[key]:{...(typeof before==='object'&&before&&!Array.isArray(before)?before:typeof before==='string'?{[baseLocale]:before}:{}),[lang]:value}}};}
 function patch(key:string,value:unknown){draft={...draft,content:{...draft.content,[key]:value}};}
 function addLanguage(){if(!/^[a-z]{2,3}(-[A-Z]{2})?$/.test(customLang)){error='Usa un código de idioma como es, en o pt-BR.';return;}lang=customLang;writeField('body','');customLang='';error='';}
 function addHint(){const hints=draft.content.hints??[];patch('hints',[...hints,{id:crypto.randomUUID(),text:{[lang]:''},penaltyPercent:Math.min(40,(hints.length+1)*5)}]);}
 function hintText(i:number,value:string){patch('hints',draft.content.hints?.map((h,n)=>n!==i?h:{...h,text:{...(typeof h.text==='object'?h.text:{[baseLocale]:h.text}),[lang]:value}}));}
 function reorder<T>(values:T[],from:number,to:number){const next=[...values],v=next.splice(from,1)[0];next.splice(to,0,v);return next;}
 function addBlock(type:InfoBlock['type']){patch('blocks',[...(draft.content.blocks??[]),{id:crypto.randomUUID(),type,value:''}]);}
 function block(id:string,values:Partial<InfoBlock>){patch('blocks',draft.content.blocks?.map(b=>b.id===id?{...b,...values}:b));}
 function readJSON(){try{const value=importRoutingModule(JSON.parse(json),draft.id);if(value.type!==draft.type)throw Error('Selecciona un JSON del mismo tipo de módulo.');draft=value;json=JSON.stringify(exportRoutingModule(draft),null,2);error='';return true;}catch(e){error=(e as Error).message;return false;}}
 function switchTab(next:typeof tab){if(tab==='json'&&!readJSON())return;if(next==='json')json=JSON.stringify(exportRoutingModule(draft),null,2);if(next==='preview'){try{validateRoutingModule(draft);if(!routingModuleReady(draft))throw Error('Completa el módulo antes de probarlo.');previewRevision++;}catch(e){error=(e as Error).message;return;}}tab=next;error='';}
 function apply(){if(tab==='json'&&!readJSON())return;try{validateRoutingModule(draft);onapply(JSON.parse(JSON.stringify(draft)));}catch(e){error=(e as Error).message;}}
 async function importFile(e:Event){const file=(e.currentTarget as HTMLInputElement).files?.[0];fileInput.value='';if(!file)return;try{if(file.size>9_000_000)throw Error('El JSON supera 9 MB.');const value=importRoutingModule(JSON.parse(await file.text()),draft.id);if(value.type!==draft.type)throw Error('El JSON pertenece a otro tipo de módulo.');if(dirty&&!confirm(ui.text("¿Sustituir los cambios por el JSON importado?")))return;draft=value;tab='edit';error='';}catch(e){error=(e as Error).message;}}
 function exportJSON(){if(tab==='json'&&!readJSON())return;try{validateRoutingModule(draft);downloadBlob(new Blob([JSON.stringify(exportRoutingModule(draft),null,2)],{type:'application/json'}),draft.type+'-'+draft.id+'.json');}catch(e){error=(e as Error).message;}}
</script>
<svelte:window onkeydown={keys} onbeforeunload={unload}/>
<section class="routing-editor" aria-label={ui.text("Editor de ")+ui.text(labels[draft.type])}><ModuleEditorHeader title={ui.text(labels[draft.type])} context={title} onclose={leave}/><nav aria-label={ui.text("Vistas del editor de módulo")}><button aria-pressed={tab==='edit'} onclick={()=>switchTab('edit')}>{ui.text("Contenido")}</button><button aria-pressed={tab==='json'} onclick={()=>switchTab('json')}>JSON</button><button aria-pressed={tab==='preview'} onclick={()=>switchTab('preview')}><Play size={15}/> {ui.text("Probar")}</button><span></span><button aria-label={ui.text("Importar JSON de módulo")} title={ui.text("Importar JSON")} onclick={()=>fileInput.click()}><Upload size={15}/></button><button aria-label={ui.text("Exportar JSON de módulo")} title={ui.text("Exportar JSON")} onclick={exportJSON}><Download size={15}/></button></nav><input class="hidden" type="file" accept="application/json,.json" bind:this={fileInput} onchange={importFile}/>
 {#if error}<p class="error" role="alert">{ui.text(error)}</p>{/if}{#if discarding}<div class="discard" role="alert"><p>{ui.text("¿Descartar los cambios de este módulo?")}</p><button onclick={onclose}>{ui.text("Descartar")}</button><button onclick={()=>discarding=false}>{ui.text("Seguir editando")}</button></div>{/if}
 <div class="content">{#if tab==='json'}<label>{ui.text("JSON de RoutingTales")}<textarea class="json" aria-label={ui.text("JSON del módulo")} bind:value={json} rows="24"></textarea></label>
 {:else if tab==='preview'}{#key previewRevision}<RoutingModulePlayer module={draft} storage={previewStorage} progressKey={'preview:'+previewRevision} currentLang={lang} preview onstate={()=>true} oncontinue={()=>switchTab('edit')} onclose={()=>switchTab('edit')}/>{/key}
 {:else}<label>{ui.text("Nombre del módulo")}<input aria-label={ui.text("Nombre del módulo")} bind:value={draft.title} maxlength="120"/></label><div class="language"><label>{ui.text("Idioma")}<select aria-label={ui.text("Idioma del contenido")} bind:value={lang}>{#each languages as l}<option value={l}>{l}</option>{/each}</select></label><input aria-label={ui.text("Nuevo idioma")} bind:value={customLang} placeholder={ui.text("en, fr…")}/><button aria-label={ui.text("Añadir idioma")} onclick={addLanguage}><Plus size={15}/></button></div><label>{ui.text("Título en este idioma")}<input aria-label={ui.text("Título del contenido")} value={localizedField('title')} oninput={e=>writeField('title',e.currentTarget.value)} maxlength="120"/></label>
 <p class="field-label">{draft.type==='question'?ui.text("Enunciado"):ui.text("Contenido")}</p><RichTextEditor interfaceLocale={ui.locale} label={draft.type==='question'?ui.text("Enunciado"):ui.text("Contenido")} value={localizedField('body')} toolbarMode="enhanced" placeholder={draft.type==='question'?ui.text("Escribe la pregunta…"):ui.text("Escribe el contenido…")} on:change={e=>writeField('body',e.detail)}/>
 {#if draft.type==='question'}<details open><summary>{ui.text("Respuesta y modo de interacción")}</summary><label>{ui.text("Respuestas correctas")}<input aria-label={ui.text("Respuestas correctas")} value={localizedField('answer')} oninput={e=>writeField('answer',e.currentTarget.value)} placeholder={ui.text("Alternativas separadas con |")}/></label><label>{ui.text("Modo de respuesta")}<select aria-label={ui.text("Modo de respuesta")} value={draft.content.answerMode??'TEXT'} onchange={e=>patch('answerMode',e.currentTarget.value)}>{#each answerModes as mode}<option value={mode}>{({TEXT:ui.text("Texto libre"),LETTER_SLOTS:ui.text("Casillas de letras"),NUMERIC_DIAL:ui.text("Combinación numérica"),LETTER_DIAL:ui.text("Combinación de letras"),LETTER_ORDER:ui.text("Ordenar letras")})[mode]}</option>{/each}</select></label>{#if draft.content.answerMode==='LETTER_SLOTS'}<label>{ui.text("Número de posiciones (automático si vacío)")}<input aria-label={ui.text("Número de posiciones")} type="number" min="1" max="40" value={draft.content.slotLength??''} onchange={e=>patch('slotLength',e.currentTarget.value?+e.currentTarget.value:null)}/></label>{/if}{#if draft.content.answerMode==='LETTER_ORDER'||draft.content.answerMode==='LETTER_DIAL'}<label>{ui.text("Alfabeto disponible (opcional)")}<input aria-label={ui.text("Alfabeto disponible")} value={draft.content.answerAlphabet?.join('')??''} oninput={e=>patch('answerAlphabet',e.currentTarget.value?[...e.currentTarget.value]:undefined)}/></label>{/if}{#if draft.content.answerMode==='LETTER_ORDER'}<label>{ui.text("Letras para ordenar (opcional)")}<input aria-label={ui.text("Letras para ordenar")} value={draft.content.answerLetters?.join('')??''} oninput={e=>patch('answerLetters',e.currentTarget.value?[...e.currentTarget.value]:undefined)}/></label>{/if}<label>{ui.text("Intentos máximos (0 = sin límite)")}<input aria-label={ui.text("Intentos máximos")} type="number" min="0" max="100" value={draft.content.maxAttempts??0} onchange={e=>patch('maxAttempts',+e.currentTarget.value)}/></label></details>
 <details><summary>{ui.text("Pistas progresivas ·")} {draft.content.hints?.length??0}</summary>{#each draft.content.hints??[] as h,i (h.id)}<details class="card" open><summary>{ui.text("Pista")} {i+1}</summary><textarea aria-label={ui.text("Texto de pista ")+(i+1)} rows="2" value={localized(h.text,lang)} oninput={e=>hintText(i,e.currentTarget.value)}></textarea><label>{ui.text("Penalización (%)")}<input type="number" min="0" max="40" value={h.penaltyPercent} onchange={e=>patch('hints',draft.content.hints?.map(v=>v.id===h.id?{...v,penaltyPercent:+e.currentTarget.value}:v))}/></label><div class="actions"><button aria-label={ui.text("Subir pista ")+(i+1)} disabled={i===0} onclick={()=>patch('hints',reorder(draft.content.hints!,i,i-1))}><ArrowUp size={15}/></button><button aria-label={ui.text("Bajar pista ")+(i+1)} disabled={i===draft.content.hints!.length-1} onclick={()=>patch('hints',reorder(draft.content.hints!,i,i+1))}><ArrowDown size={15}/></button><button aria-label={ui.text("Eliminar pista ")+(i+1)} onclick={()=>patch('hints',draft.content.hints?.filter(v=>v.id!==h.id))}><Trash2 size={15}/></button></div></details>{/each}<button disabled={(draft.content.hints?.length??0)>=16} onclick={addHint}><Plus size={15}/> {ui.text("Añadir pista")}</button></details>{/if}
 {#if draft.type==='video'}<MediaField label={ui.text("Vídeo")} kind="video" value={localizedField('videoUrl')} onchange={v=>writeField('videoUrl',v)}/><label>{ui.text("Visionado requerido (%)")}<input aria-label={ui.text("Visionado requerido")} type="number" min="1" max="100" value={draft.content.requiredWatchPercent??80} onchange={e=>patch('requiredWatchPercent',+e.currentTarget.value)}/></label>{/if}
 <details><summary>{ui.text("Imagen y efectos")}</summary><MediaField label={draft.type==='video'?ui.text("Miniatura"):ui.text("Imagen")} value={draft.content.image} onchange={v=>patch('image',v)}/>{#if draft.type!=='video'}<label>{ui.text("Efecto de imagen")}<select aria-label={ui.text("Efecto de imagen")} value={draft.content.imageInteractionMode??'NONE'} onchange={e=>patch('imageInteractionMode',e.currentTarget.value)}>{#each imageModes as mode}<option value={mode}>{({NONE:ui.text("Sin efecto"),TORCH:ui.text("Linterna"),MAGNIFIER:ui.text("Lupa"),XRAY:ui.text("Rayos X"),SCRATCH:ui.text("Rascar"),SLIDER:ui.text("Comparar con deslizador")})[mode]}</option>{/each}</select></label>{#if ['XRAY','SCRATCH','SLIDER'].includes(draft.content.imageInteractionMode??'')}<MediaField label={ui.text("Segunda imagen")} value={draft.content.xrayImage} onchange={v=>patch('xrayImage',v)}/>{/if}<label>{ui.text("Proporción de imagen")}<input aria-label={ui.text("Proporción de imagen")} value={draft.content.imageAspectRatio??'16:9'} onchange={e=>patch('imageAspectRatio',e.currentTarget.value)}/></label>{#each [{key:'torchRadius',label:'Radio de linterna',min:40,max:320,default:130},{key:'magnifierZoom',label:'Zoom de lupa',min:1.2,max:4,default:2},{key:'magnifierRadius',label:'Radio de lupa',min:60,max:240,default:120},{key:'xrayRadius',label:'Radio de rayos X',min:60,max:260,default:120},{key:'scratchRadius',label:'Radio de rasca',min:20,max:120,default:56}] as f}<label>{ui.text(f.label??'')}<input type="number" min={f.min} max={f.max} step={f.key==='magnifierZoom'?.1:1} value={Number(draft.content[f.key]??f.default)} onchange={e=>patch(f.key,+e.currentTarget.value)}/></label>{/each}{/if}</details>
 {#if draft.type!=='video'}<details><summary>{ui.text("Audio y vídeo de apoyo")}</summary><MediaField label={ui.text("Audio")} kind="audio" value={localizedField('audio')} onchange={v=>writeField('audio',v)}/><MediaField label={ui.text("Multimedia de apoyo")} kind="media" value={localizedField('mediaUrl')} onchange={v=>writeField('mediaUrl',v)}/>{#if draft.type==='info'}<label>{ui.text("Porcentaje requerido de escucha/visionado")}<input type="number" min="1" max="100" value={draft.content.requiredWatchPercent??80} onchange={e=>patch('requiredWatchPercent',+e.currentTarget.value)}/></label><label class="check"><input type="checkbox" checked={draft.content.backgroundAudio===true} onchange={e=>patch('backgroundAudio',e.currentTarget.checked)}/> {ui.text("Continuar el audio al cerrar el módulo")}</label>{/if}</details>{/if}
 {#if draft.type==='info'}<details><summary>{ui.text("Bloques adicionales ·")} {draft.content.blocks?.length??0}</summary>{#each draft.content.blocks??[] as b,i (b.id)}<details class="card" open><summary>{i+1}. {b.type==='text'?ui.text("Texto"):ui.text("Imagen")}</summary>{#if b.type==='text'}<RichTextEditor interfaceLocale={ui.locale} value={b.value} toolbarMode="enhanced" on:change={e=>block(b.id,{value:e.detail})}/>{:else}<MediaField label={ui.text("Imagen del bloque ")+(i+1)} value={b.value} onchange={v=>block(b.id,{value:v})}/><label>{ui.text("Pie de imagen")}<input value={b.caption??''} oninput={e=>block(b.id,{caption:e.currentTarget.value})}/></label>{/if}<div class="actions"><button disabled={i===0} aria-label={ui.text("Subir bloque ")+(i+1)} onclick={()=>patch('blocks',reorder(draft.content.blocks!,i,i-1))}><ArrowUp size={15}/></button><button disabled={i===draft.content.blocks!.length-1} aria-label={ui.text("Bajar bloque ")+(i+1)} onclick={()=>patch('blocks',reorder(draft.content.blocks!,i,i+1))}><ArrowDown size={15}/></button><button aria-label={ui.text("Eliminar bloque ")+(i+1)} onclick={()=>patch('blocks',draft.content.blocks?.filter(v=>v.id!==b.id))}><Trash2 size={15}/></button></div></details>{/each}<button onclick={()=>addBlock('text')}>{ui.text("+ Texto")}</button><button onclick={()=>addBlock('image')}>{ui.text("+ Imagen")}</button></details>{/if}
 <details><summary>{ui.text("Puntuación y mensajes")}</summary><label>{ui.text("Puntos al completar")}<input aria-label={ui.text("Puntos al completar")} type="number" min="0" max="999999" bind:value={draft.points.win}/></label><label>{ui.text("Puntos al fallar")}<input aria-label={ui.text("Puntos al fallar")} type="number" min="0" max="999999" bind:value={draft.points.fail}/></label>{#if draft.type==='question'}<label>{ui.text("Penalización por intento fallido (%)")}<input type="number" min="0" max="40" value={draft.points.failurePenaltyPercent??10} onchange={e=>draft.points={...draft.points,failurePenaltyPercent:+e.currentTarget.value}}/></label>{/if}{#each ['win','fail'] as outcome}<label>{outcome==='win'?ui.text("Mensaje al completar"):ui.text("Mensaje al fallar")}<textarea rows="2" value={draft.points.context?.[outcome as 'win'|'fail']??''} oninput={e=>draft.points={...draft.points,context:{...draft.points.context,[outcome]:e.currentTarget.value}}}></textarea></label>{/each}</details>
 {/if}</div><footer><small>{ui.text("Aplicar al borrador y guardar la aventura.")}</small><button class="apply" onclick={apply}><Save size={16}/> {ui.text("Aplicar módulo")}</button></footer></section>
<style>.routing-editor{display:flex;flex-direction:column;min-height:0;height:100%;font-size:12px;color:#35502f}.content{flex:1;min-height:0;overflow:auto;padding:16px}nav,.actions,.language{display:flex;align-items:center;gap:5px}nav{padding:10px;border-bottom:1px solid #dce5d6;flex-wrap:wrap}nav span{flex:1}button{display:inline-flex;align-items:center;gap:5px;flex:none;padding:8px;border:1px solid #d5dfce;border-radius:7px;background:white;color:inherit;font:inherit;cursor:pointer}button:disabled{opacity:.4;cursor:default}button[aria-pressed=true],.apply{background:#dfeccd}label{display:block;margin:12px 0}input,select,textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfce;border-radius:7px;color:inherit;font:inherit;background:#fff}label>input,label>select,label>textarea{display:block;margin-top:7px}.language label{flex:1}.language>input{flex:1;min-width:0}.json{font-family:monospace;min-height:50vh}.check{display:flex;align-items:center;gap:7px}.check input{width:16px}details{padding:14px 0;border-top:1px solid #dce5d6;margin-top:16px}summary{font-weight:600;cursor:pointer}.card{border:1px solid #d5dfce;border-radius:8px;padding:12px}.actions{justify-content:flex-end}.hidden{display:none}.error{color:#9b4535;padding:0 15px}.discard{padding:12px;background:#fff5e8}footer{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px;border-top:1px solid #dce5d6;flex:none}footer small{color:#718269}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:2px solid #789557;outline-offset:2px}</style>
